      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        ...children,
        // A submission the server refused: the same danger-toned callout, text only.
        if (error != null) CruftFreeCallout(text: error, failure: true, icon: Icons.error_outline),
        Align(
