  bool _revealed = false;

  @override
  void didUpdateWidget(covariant CruftFreeTextField oldWidget) {
    super.didUpdateWidget(oldWidget);
    final text = cruftfreeFieldText(widget.model.valueAt(widget.path));
    if (cruftfreeParseField(widget.kind, _controller.text) != widget.model.valueAt(widget.path) && _controller.text != text) {
      _controller.text = text;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  TextInputType get _keyboard =>
      cruftfreeKeyboard(widget.inputMode) ??
      switch (widget.kind) {
        CruftFreeFieldKind.integer => TextInputType.number,
        CruftFreeFieldKind.number || CruftFreeFieldKind.decimalText => const TextInputType.numberWithOptions(decimal: true, signed: true),
        CruftFreeFieldKind.date || CruftFreeFieldKind.time || CruftFreeFieldKind.dateTime => TextInputType.datetime,
        CruftFreeFieldKind.secret => TextInputType.visiblePassword,
        _ => widget.multiline ? TextInputType.multiline : TextInputType.text,
      };

