    padding: EdgeInsets.all(CruftFreeTokens.of(context).inset),
    child: CruftFreeColorPickButton(
      value: widget.model.valueAt(widget.path) as String?,
      label: widget.label,
      enabled: !widget.readOnly,
      onPicked: (color) {
        _controller.text = color;
        widget.model.setValue(widget.path, color);
      },
    ),
  );

  String? _validate(String? text) {
    final entered = text ?? '';
    final value = cruftfreeParseField(widget.kind, entered);
    if (entered.isNotEmpty && value == null) {
      return cruftfreeRuntime.messages.key('framework.invalid').text;
    }
    return widget.rules.check(value);
