      decoration: InputDecoration(
        labelText: widget.label,
        hintText: cruftfreeHintText(widget.placeholder),
        errorText: widget.model.serverErrorAt(widget.path),
        suffixIcon: secret ? cruftfreeRevealControl(revealed: _revealed, enabled: !widget.readOnly, onToggle: () => setState(() => _revealed = !_revealed)) : null,
