/// One money field: a whole number of a currency's minor units, written and shown as the
/// major-unit amount of the currency ([currency] names it) -- `25.00` for 2500 EUR cents, `2500`
/// for 2500 JPY -- in the session locale's decimal separator. The value the model holds is always
/// the whole number, so the amount that reaches the server is exact. Text that is no amount for the
/// currency (a stray letter, a cent and a half) is never rounded: the field shows it is invalid and
/// holds no value. While [currency] names no code the formatting data carries, the field is
/// read-only and empty, and keeps the value the model holds.
class CruftFreeMoneyField extends StatefulWidget {
  const CruftFreeMoneyField({super.key, required this.model, required this.path, required this.label, required this.currency, this.placeholder, this.rules = const FieldRules(), this.readOnly = false});

  final CruftFreeFormModel model;
  final String path;
  final String label;

  /// The example shown while the field is empty; never a substitute for [label].
  final String? placeholder;

  /// The ISO 4217 code of the currency the amount is in, read whenever the form changes.
  final String? Function() currency;
  final FieldRules rules;
  final bool readOnly;

  @override
  State<CruftFreeMoneyField> createState() => _CruftFreeMoneyFieldState();
}

class _CruftFreeMoneyFieldState extends State<CruftFreeMoneyField> {
  final TextEditingController _controller = TextEditingController();
  String? _shownCurrency;

  @override
  void initState() {
    super.initState();
    _show();
    widget.model.addListener(_sync);
  }

  @override
  void didUpdateWidget(covariant CruftFreeMoneyField oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.model != widget.model) {
      oldWidget.model.removeListener(_sync);
      widget.model.addListener(_sync);
    }
    _sync();
  }

  @override
  void dispose() {
    widget.model.removeListener(_sync);
    _controller.dispose();
    super.dispose();
  }

  /// The currency the field edits in, or `null` while it names no code the data carries.
  String? get _code {
    final code = widget.currency();
    return code != null && cruftfreeRuntime.format.knowsCurrency(code) ? code : null;
  }

  int? get _held {
    final value = widget.model.valueAt(widget.path);
    return value is int ? value : null;
  }

  void _show() {
    final code = _code;
    final held = _held;
    _shownCurrency = code;
    _controller.text = code == null || held == null ? '' : cruftfreeRuntime.format.minorMoneyInputText(held, code);
  }

  /// Rewrites the text only when what it shows changed under it -- a new currency, or a value the
  /// form was given -- never while the person types: text that is no amount stays as typed.
  void _sync() {
    final code = _code;
    final parsed = code == null ? null : cruftfreeRuntime.format.parseMinorMoneyInput(_controller.text, code);
    final typedAmount = parsed is MinorUnitsAmount ? parsed.minorUnits : null;
    if (code != _shownCurrency || (parsed is! MinorUnitsInvalid && typedAmount != _held)) {
      _show();
    }
  }

  String? _validate(String? text) {
    final code = _code;
    if (code == null) {
      return widget.rules.check(widget.model.valueAt(widget.path));
    }
    final parsed = cruftfreeRuntime.format.parseMinorMoneyInput(text ?? '', code);
    if (parsed is MinorUnitsInvalid) {
      return cruftfreeRuntime.messages.key('framework.invalid').text;
    }
    return widget.rules.check(parsed is MinorUnitsAmount ? parsed.minorUnits : null);
  }

  void _changed(String text) {
    final code = _code;
    if (code == null) {
      return;
    }
    final parsed = cruftfreeRuntime.format.parseMinorMoneyInput(text, code);
    widget.model.setValue(widget.path, parsed is MinorUnitsAmount ? parsed.minorUnits : null);
  }

  @override
  Widget build(BuildContext context) {
    return TextFormField(
      controller: _controller,
      readOnly: widget.readOnly || _code == null,
      keyboardType: const TextInputType.numberWithOptions(decimal: true, signed: true),
      decoration: InputDecoration(labelText: widget.label, hintText: cruftfreeHintText(widget.placeholder), errorText: widget.model.serverErrorAt(widget.path)),
      validator: _validate,
      onChanged: _changed,
    );
  }
}

