  final String path;
  final String label;

  /// One choice per row of the route now offered: the key the field holds and the text it is shown by.
  final List<CruftFreeOption<Object>> Function() choices;

  /// The row the form found for the key it holds when its row is on no page shown; `null` without.
  final CruftFreeOption<Object>? Function()? known;

  /// Whether a list read whole is presented as one selectable card per choice.
  final bool cards;

  /// The paginated route's binding the choices come from; `null` for a list read whole.
  final PagedBinding<Object?>? pages;

  /// The filter of [pages] the typed text is sent as; `null` narrows the loaded choices instead.
  final String? search;

  /// The row picked, or `null` when the choice is cleared: a review shows its text.
  final ValueChanged<CruftFreeOption<Object>?>? onPicked;
  final FieldRules rules;
  final bool readOnly;

  @override
  Widget build(BuildContext context) {
    return FormField<Object>(
      initialValue: model.valueAt(path),
      validator: (_) => rules.check(model.valueAt(path)),
      builder: (field) => CruftFreeChoicePicker<Object>(
        label: label,
        value: model.valueAt(path),
        choices: choices,
        known: known,
        cards: cards,
        pages: pages,
        search: search,
        enabled: !readOnly,
        errorText: field.errorText ?? model.serverErrorAt(path),
        onChanged: (value, choice) {
          model.setValue(path, value);
          field.didChange(value);
          onPicked?.call(choice);
        },
        onCleared: () {
          model.setValue(path, null);
          field.didChange(null);
          onPicked?.call(null);
        },
      ),
    );
  }
}

/// A choice of several keys among the rows of a route, held as the elements of the field's array in
/// the order picked: a `CruftFreeMultiChoicePicker` (a group of checkboxes, or a searched picker for a long
/// list or a paginated route). The picker owns no state of the keys: every pick or removal writes the
/// keys held after it into the model, the picker's [onPicked] keeping the rows picked for a review.
class CruftFreeMultiChoiceListField extends StatelessWidget {
  const CruftFreeMultiChoiceListField({super.key, required this.model, required this.path, required this.label, required this.choices, this.known, this.cards = false, this.pages, this.search, this.onPicked, this.readOnly = false});

  final CruftFreeFormModel model;
  final String path;
  final String label;

  /// One choice per row of the route now offered: the key the field holds and the text it is shown by.
  final List<CruftFreeOption<Object>> Function() choices;

  /// The rows the form found for the keys it holds whose rows are on no page shown; `null` without.
  final List<CruftFreeOption<Object>> Function()? known;

  /// Whether a list read whole is presented as one selectable card per choice.
  final bool cards;

  /// The paginated route's binding the choices come from; `null` for a list read whole.
  final PagedBinding<Object?>? pages;

  /// The filter of [pages] the typed text is sent as; `null` narrows the loaded choices instead.
  final String? search;

  /// Every row picked so far: a review shows their text.
  final ValueChanged<List<CruftFreeOption<Object>>>? onPicked;
  final bool readOnly;

  @override
  Widget build(BuildContext context) {
    return CruftFreeMultiChoicePicker<Object>(label: label, values: model.itemsAt(path).whereType<Object>().toList(), choices: choices, known: known, cards: cards, pages: pages, search: search, enabled: !readOnly, errorText: model.serverErrorAt(path), onPicked: onPicked, onChanged: (keys) => model.setValue(path, keys));
  }
}

/// A yes/no field.
class CruftFreeToggleField extends StatelessWidget {
  const CruftFreeToggleField({super.key, required this.model, required this.path, required this.label, this.readOnly = false});

