/// A file chosen from the device, sent as a multipart part.
class CruftFreeFileField extends StatelessWidget {
  const CruftFreeFileField({super.key, required this.model, required this.path, required this.label, this.rules = const FieldRules(), this.readOnly = false});

  final CruftFreeFormModel model;
  final String path;
  final String label;
  final FieldRules rules;
  final bool readOnly;

  Future<void> _choose() async {
    final file = await cruftfreeRuntime.media.pickFile(null);
    if (file != null) {
      model.setValue(path, file);
    }
  }

  @override
  Widget build(BuildContext context) {
    final chosen = model.valueAt(path);
    return FormField<Object?>(
      initialValue: chosen,
      validator: (_) => rules.check(model.valueAt(path)),
      builder: (state) => InputDecorator(
        decoration: InputDecoration(labelText: label, errorText: state.errorText ?? model.serverErrorAt(path)),
        child: Row(
          children: [
            Expanded(child: Text(chosen is UploadFile ? chosen.filename : '')),
            TextButton(onPressed: readOnly ? null : _choose, child: Text(cruftfreeRuntime.messages.key('framework.add').text)),
          ],
        ),
      ),
    );
  }
}

/// A repeatable field: its items, each with a remove action, and an add action.
class CruftFreeRepeatable extends StatelessWidget {
  const CruftFreeRepeatable({super.key, required this.model, required this.path, required this.label, required this.item, required this.create});

  final CruftFreeFormModel model;
  final String path;
  final String label;

  /// The widgets of the item at an index.
  final List<Widget> Function(int index) item;

  /// A new item's empty value.
  final Object? Function() create;

  @override
  Widget build(BuildContext context) {
    final messages = cruftfreeRuntime.messages;
    final count = model.itemsAt(path).length;
    return CruftFreeFieldSection(
      title: label,
      children: [
        for (var index = 0; index < count; index++) ...[
          ...item(index),
          Align(
            alignment: AlignmentDirectional.centerEnd,
            child: TextButton(onPressed: () => model.removeItem(path, index), child: Text(messages.key('framework.remove').text)),
          ),
        ],
        Align(
          alignment: AlignmentDirectional.centerStart,
          child: TextButton(onPressed: () => model.addItem(path, create()), child: Text(messages.key('framework.add').text)),
        ),
      ],
    );
  }
}

/// How a review step shows one field's value.
enum CruftFreeReviewKind { text, number, money, percent, date, dateTime, time, boolean, choice, file }

/// [value] as the text a review step shows -- always plain text, never markup.
/// A field left unset shows the framework's not-provided text, a boolean yes or
/// no, a choice its option label ([options] maps each wire value to its label),
/// a file its name, and a number, money, percent, date or time its locale
/// format. A text the format cannot read (a value typed into a plain text
/// input, which the server validates) is shown exactly as typed.
String cruftfreeReviewText(Object? value, CruftFreeReviewKind kind, [Map<String, String> options = const {}]) {
  final messages = cruftfreeRuntime.messages;
  if (value == null || (value is String && value.isEmpty)) {
    return messages.key('framework.notProvided').text;
  }
  final format = cruftfreeRuntime.format;
  return switch (kind) {
    CruftFreeReviewKind.boolean => messages.key(value == true ? 'framework.yes' : 'framework.no').text,
    CruftFreeReviewKind.choice => options[value] ?? (throw StateError('A choice field holds a value that is none of its options.')),
    CruftFreeReviewKind.file => value is UploadFile ? value.filename : (throw StateError('A file field holds a value that is not a file.')),
    CruftFreeReviewKind.number => _cruftfreeReviewNumber(value, format.number),
    CruftFreeReviewKind.money => _cruftfreeReviewNumber(value, format.money),
    CruftFreeReviewKind.percent => _cruftfreeReviewNumber(value, format.percent),
    CruftFreeReviewKind.date => _cruftfreeReviewTemporal(value, format.date),
    CruftFreeReviewKind.dateTime => _cruftfreeReviewTemporal(value, format.dateTime),
    CruftFreeReviewKind.time => _cruftfreeReviewTemporal(value, format.time),
    CruftFreeReviewKind.text => '$value',
  };
}

/// A number, or an exact decimal's text formatted exactly; any other value as it reads.
String _cruftfreeReviewNumber(Object value, String Function(Object) format) {
  if (value is num) {
    return format(value);
  }
  final text = '$value';
  return cruftfreeIsDecimalText(text) ? format(text) : text;
}

String _cruftfreeReviewTemporal(Object value, String Function(String) format) {
  final text = '$value';
  return DateTime.tryParse(text) == null ? text : format(text);
}

