/// One step of a multi-step form: its title, the top-level fields it owns
/// ([roots]; none for a review step) and what it shows.
class CruftFreeFormStep {
  const CruftFreeFormStep({required this.title, required this.roots, required this.children});

  final String title;
  final List<String> roots;
  final List<Widget> children;
}

/// A multi-step form: one step's panel at a time, each step validated alone
/// before the form moves on, and the Back, Next and submit controls. At and
/// above [horizontalFrom] the steps are numbered markers joined by lines above
/// the panel; below it, or when it is `null`, they stack as a Material
/// [Stepper]. A completed step can be returned to; a step ahead cannot be
/// opened. A failed submission reveals the first step holding a field error.
class CruftFreeStepperFormView extends StatefulWidget {
  const CruftFreeStepperFormView({super.key, required this.model, required this.steps, required this.onSubmit, this.onRetry, this.horizontalFrom, required this.submitKey, required this.nextKey, required this.backKey, this.honeypot});

  final CruftFreeFormModel model;
  final List<CruftFreeFormStep> steps;
  final VoidCallback onSubmit;

  /// The message keys wording the submit, next and back controls: the form's own labels, else the
  /// framework strings.
  final String submitKey;
  final String nextKey;
  final String backKey;

  /// Loads the starting values again after a failed load.
  final VoidCallback? onRetry;

  /// The width from which the steps lay out side by side, or `null` to
  /// always stack them.
  final double? horizontalFrom;

  /// A `honeypot` form's hidden control (`CruftFreeHoneypotField`), after everything else.
  final Widget? honeypot;

  @override
  State<CruftFreeStepperFormView> createState() => _CruftFreeStepperFormViewState();
}

class _CruftFreeStepperFormViewState extends State<CruftFreeStepperFormView> {
  int _current = 0;
  int _seenFailures = 0;
  late final List<GlobalKey<FormState>> _keys = List.generate(widget.steps.length, (_) => GlobalKey<FormState>());

  @override
  void initState() {
    super.initState();
    _seenFailures = widget.model.failureCount;
    widget.model.addListener(_revealFailedStep);
  }

  @override
  void dispose() {
    widget.model.removeListener(_revealFailedStep);
    super.dispose();
  }

  void _revealFailedStep() {
    final model = widget.model;
    if (model.failureCount == _seenFailures) {
      return;
    }
    _seenFailures = model.failureCount;
    final index = widget.steps.indexWhere((step) => model.hasServerErrorUnder(step.roots));
    if (index >= 0 && index != _current && mounted) {
      setState(() => _current = index);
    }
  }

  bool get _last => _current == widget.steps.length - 1;

  /// Validates only the shown step's own fields.
  bool _shownStepIsValid() => _keys[_current].currentState?.validate() ?? false;

  void _next() {
    if (_shownStepIsValid()) {
      setState(() => _current += 1);
    }
  }

  void _back() => setState(() => _current -= 1);

  void _goTo(int index) {
    if (index < _current) {
      setState(() => _current = index);
    }
  }

  void _submit() {
    if (_shownStepIsValid()) {
      widget.onSubmit();
    }
  }

  Widget _panel(int index) {
    return Form(
      key: _keys[index],
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, mainAxisSize: MainAxisSize.min, children: widget.steps[index].children),
    );
  }

  Widget _controls() {
    final messages = cruftfreeRuntime.messages;
    return Wrap(
      spacing: 8,
      children: [
        if (_current > 0) TextButton(onPressed: _back, child: Text(messages.key(widget.backKey).text)),
        _last ? CruftFreeButton(kind: CruftFreeButtonKind.primary, label: messages.key(widget.submitKey).text, busy: widget.model.submitting, onPressed: _submit) : FilledButton(onPressed: _next, child: Text(messages.key(widget.nextKey).text)),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final gate = _cruftfreeFormGate(widget.model, widget.onRetry);
    if (gate != null) {
      return gate;
    }
    final error = widget.model.formError;
    final from = widget.horizontalFrom;
    final wide = from != null && MediaQuery.sizeOf(context).width >= from;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        wide ? _sideBySide() : _stacked(),
        // A submission the server refused: the same danger-toned callout, text only.
        if (error != null) CruftFreeCallout(text: error, failure: true, icon: Icons.error_outline),
        ?widget.honeypot,
      ],
    );
  }

  /// The steps as numbered markers joined by lines above the shown panel.
  Widget _sideBySide() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        _CruftFreeStepperHeader(titles: widget.steps.map((step) => step.title).toList(), current: _current, onTap: _goTo),
        _panel(_current),
        _controls(),
      ],
    );
  }

  /// The steps stacked as a Material [Stepper]; a step ahead is disabled, so
  /// it cannot be opened.
  Widget _stacked() {
    return Stepper(physics: const NeverScrollableScrollPhysics(), currentStep: _current, onStepTapped: _goTo, controlsBuilder: (context, details) => _controls(), steps: List.generate(widget.steps.length, _step));
  }

  Step _step(int index) {
    return Step(title: Text(widget.steps[index].title), isActive: index == _current, state: _stateOf(index), content: _panel(index));
  }

  StepState _stateOf(int index) {
    if (index < _current) {
      return StepState.complete;
    }
    return index == _current ? StepState.indexed : StepState.disabled;
  }
}

/// The numbered markers of a wide multi-step form, joined by lines: done (a
/// check), the current step and the steps ahead (muted). Only a done marker
/// can be tapped.
class _CruftFreeStepperHeader extends StatelessWidget {
  const _CruftFreeStepperHeader({required this.titles, required this.current, required this.onTap});

  final List<String> titles;
  final int current;
  final void Function(int index) onTap;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Row(
      children: [
        for (var index = 0; index < titles.length; index++) ...[
          if (index > 0) Expanded(child: Divider(color: index <= current ? scheme.primary : null)),
          Semantics(
            selected: index == current,
            child: InkResponse(
              onTap: index < current ? () => onTap(index) : null,
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  CircleAvatar(backgroundColor: index <= current ? scheme.primary : scheme.surfaceContainerHighest, foregroundColor: index <= current ? scheme.onPrimary : scheme.onSurfaceVariant, child: index < current ? const Icon(Icons.check) : Text('${index + 1}')),
                  Padding(
                    padding: const EdgeInsetsDirectional.only(start: 8, end: 8),
                    child: Text(titles[index], style: index == current ? const TextStyle(fontWeight: FontWeight.w600) : null),
                  ),
                ],
              ),
            ),
          ),
        ],
      ],
    );
  }
}
